var question_studio_review_library_chunk_6_default = "";

// src/quant-v4/topics/Arithmetic/subtopics/ProfitAndLoss/PNL-001/question-studio-review.library.ts
var COMPRESSED_LIBRARY_BASE64 = [
  question_studio_review_library_chunk_0_default,
  question_studio_review_library_chunk_1_default,
  question_studio_review_library_chunk_2_default,
  question_studio_review_library_chunk_3_default,
  question_studio_review_library_chunk_4_default,
  question_studio_review_library_chunk_5_default,
  question_studio_review_library_chunk_6_default
].join("");
var PNL_001_CANONICAL_REVIEW_LIBRARY = JSON.parse(
  brotliDecompressSync(
    Buffer.from(COMPRESSED_LIBRARY_BASE64, "base64")
  ).toString("utf8")
);

// src/quant-v4/topics/Arithmetic/subtopics/ProfitAndLoss/PNL-001/question-studio-review-runtime.ts
var PNL_001_ARCHETYPE_ID = "PNL-001";
var PNL_001_CP_IDS = [
  "PNL-CP-001",
  "PNL-CP-002",
  "PNL-CP-003",
  "PNL-CP-004",
  "PNL-CP-005",
  "PNL-CP-006"
];
var reviewLibrary = PNL_001_CANONICAL_REVIEW_LIBRARY;
var entries = Object.values(reviewLibrary.entries);
function hashSeed(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}
function selectReviewEntry(cpId, input) {
  if (input.language && input.language !== "en") {
    throw new Error("PNL-001 canonical review runtime currently supports English only.");
  }
  if (input.questionLanguageId) {
    const forced = reviewLibrary.entries[input.questionLanguageId];
    if (!forced) {
      throw new Error(`Unknown PNL-001 question-language ID: ${input.questionLanguageId}`);
    }
    if (forced.cpId !== cpId) {
      throw new Error(
        `${input.questionLanguageId} belongs to ${forced.cpId}, not ${cpId}.`
      );
    }
    return forced;
  }
  const eligible = entries.filter(
    (entry) => entry.cpId === cpId && (!input.difficultyBand || entry.difficulty === input.difficultyBand)
  );
  if (!eligible.length) {
    throw new Error(
      `No PNL-001 canonical review entries match ${cpId}` + (input.difficultyBand ? ` at ${input.difficultyBand} difficulty.` : ".")
    );
  }
  const seed = input.seed ?? `${cpId}:canonical-review`;
  return eligible[hashSeed(seed) % eligible.length];
}
function getPnl001ActiveCanonicalProblemIds() {
  return [...PNL_001_CP_IDS];
}
function listPnl001CanonicalReviewEntries() {
  return [...entries];
}
function runPnl001ReviewPipeline(cpId, input = {}) {
  if (!PNL_001_CP_IDS.includes(cpId)) {
    throw new Error(`Unknown PNL-001 canonical problem: ${cpId}`);
  }
  const entry = selectReviewEntry(cpId, input);
  const seed = input.seed ?? `${entry.qlId}:canonical-review`;
  const explanationId = `${entry.qlId}-EXPLANATION-V2`;
  const validationChecks = [
    {
      name: "canonical-review-source",
      passed: entry.safety.runtimeMode === "CANONICAL_REVIEW",
      message: "Question is sourced from the approved canonical review library."
    },
    {
      name: "four-unique-options",
      passed: entry.options.length === 4 && new Set(entry.options).size === 4 && entry.options[entry.correctIndex] === entry.answer,
      message: "Question has four unique options and one reviewed keyed answer."
    },
    {
      name: "question-bank-safety",
      passed: entry.safety.questionBankStatus === "NOT_STORED" && entry.safety.testEligibility === "INELIGIBLE" && entry.safety.publiclyPublishable === false,
      message: "Canonical review output is not eligible for Question Bank, tests or publication."
    }
  ];
  const validation = {
    valid: validationChecks.every((check) => check.passed),
    checks: validationChecks
  };
  return {
    archetypeId: PNL_001_ARCHETYPE_ID,
    canonicalProblemId: cpId,
    questionId: `${entry.qlId}:canonical-review`,
    questionLanguageId: entry.qlId,
    explanationId,
    language: "en",
    difficultyBand: entry.difficulty,
    stem: entry.stem,
    answer: entry.answer,
    options: [...entry.options],
    correctIndex: entry.correctIndex,
    parameters: {
      archetypeId: PNL_001_ARCHETYPE_ID,
      canonicalProblemId: cpId,
      questionLanguageId: entry.qlId,
      explanationId,
      language: "en",
      difficultyBand: entry.difficulty,
      taskKind: entry.solveMode,
      answerType: "TEXT",
      representation: entry.representation,
      contextFamily: entry.contextFamily,
      seed,
      runtimeMode: entry.safety.runtimeMode,
      reviewStatus: entry.safety.reviewStatus,
      questionBankStatus: entry.safety.questionBankStatus,
      testEligibility: entry.safety.testEligibility,
      publiclyPublishable: entry.safety.publiclyPublishable
    },
    solver: {
      answer: entry.answer,
      numericAnswer: null,
      answerType: "TEXT",
      evidence: {
        source: "PNL-001 Editorial V2 canonical review",
        solveMode: entry.solveMode,
        reviewedCorrectIndex: entry.correctIndex
      },
      mathJax: {}
    },
    reasoningGraph: {
      graphId: `${entry.qlId}-canonical-review-graph`,
      nodes: [
        { id: "solve-mode", label: "Solve mode", value: entry.solveMode },
        { id: "answer", label: "Reviewed answer", value: entry.answer },
        { id: "safety", label: "Runtime status", value: entry.safety.runtimeMode }
      ]
    },
    explanation: {
      explanationId,
      lines: entry.explanation.split(/\n{2,}/)
    },
    traceability: {
      questionId: `${entry.qlId}:canonical-review`,
      canonicalProblemId: cpId,
      questionLanguageId: entry.qlId,
      explanationId,
      difficultyBand: entry.difficulty,
      taskKind: entry.solveMode,
      answerType: "TEXT",
      representation: entry.representation,
      contextFamily: entry.contextFamily,
      generationMode: "CANONICAL_REVIEW",
      source: "PNL-001 Editorial V2",
      seed,
      reviewStatus: entry.safety.reviewStatus,
      questionBankStatus: entry.safety.questionBankStatus,
      testEligibility: entry.safety.testEligibility,
      publiclyPublishable: entry.safety.publiclyPublishable
    },
    validation,
    mathJax: {}
  };
}

// src/quant-v4/topics/Arithmetic/subtopics/ProfitAndLoss/PNL-001/question-studio-review-runtime.test.ts
var entries2 = listPnl001CanonicalReviewEntries();
assert.equal(entries2.length, 186);
assert.deepEqual(getPnl001ActiveCanonicalProblemIds(), [...PNL_001_CP_IDS]);
var expectedCounts = /* @__PURE__ */ new Map([
  ["PNL-CP-001", 36],
  ["PNL-CP-002", 34],
  ["PNL-CP-003", 24],
  ["PNL-CP-004", 26],
  ["PNL-CP-005", 29],
  ["PNL-CP-006", 37]
]);
for (const cpId of PNL_001_CP_IDS) {
  assert.equal(entries2.filter((entry) => entry.cpId === cpId).length, expectedCounts.get(cpId));
}
assert.deepEqual(
  entries2.map((entry) => entry.qlId),
  Array.from({ length: 186 }, (_, index) => `PNL-QL-${String(index + 1).padStart(3, "0")}`)
);
assert.equal(new Set(entries2.map((entry) => entry.stem)).size, 186);
var unresolvedProsePlaceholder = /\{[A-Za-z][A-Za-z0-9_]*\}/;
var syntheticOpening = /^(?:consider this|during this|the following (?:commercial )?(?:situation|record|information)|use the following information|the records show)/i;
for (const entry of entries2) {
  assert.equal(entry.options.length, 4, `${entry.qlId}: option count`);
  assert.equal(new Set(entry.options).size, 4, `${entry.qlId}: duplicate option`);
  assert.equal(entry.options[entry.correctIndex], entry.answer, `${entry.qlId}: answer key`);
  assert.ok(entry.stem.trim().length >= 20, `${entry.qlId}: empty/short stem`);
  assert.ok(entry.explanation.trim().length >= 80, `${entry.qlId}: shallow explanation`);
  const proseStem = entry.stem.replace(/\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)/g, "");
  assert.equal(unresolvedProsePlaceholder.test(proseStem), false, `${entry.qlId}: unresolved prose placeholder`);
  assert.equal(syntheticOpening.test(entry.stem.trim()), false, `${entry.qlId}: synthetic opening`);
  assert.equal(entry.safety.reviewStatus, "APPROVED_EDITORIAL_CANONICAL");
  assert.equal(entry.safety.questionBankStatus, "NOT_STORED");
  assert.equal(entry.safety.testEligibility, "INELIGIBLE");
  assert.equal(entry.safety.publiclyPublishable, false);
  const pkg = runPnl001ReviewPipeline(entry.cpId, {
    questionLanguageId: entry.qlId,
    seed: `proof:${entry.qlId}`
  });
  assert.equal(pkg.questionLanguageId, entry.qlId);
  assert.equal(pkg.answer, entry.answer);
  assert.deepEqual(pkg.options, entry.options);
  assert.equal(pkg.correctIndex, entry.correctIndex);
  assert.equal(pkg.validation.valid, true);
  assert.equal(pkg.traceability.generationMode, "CANONICAL_REVIEW");
  assert.equal(pkg.traceability.questionBankStatus, "NOT_STORED");
  assert.equal(pkg.traceability.testEligibility, "INELIGIBLE");
  assert.equal(pkg.traceability.publiclyPublishable, false);
}
for (const cpId of PNL_001_CP_IDS) {
  const first = runPnl001ReviewPipeline(cpId, { seed: "deterministic-seed" });
  const second = runPnl001ReviewPipeline(cpId, { seed: "deterministic-seed" });
  assert.equal(first.questionLanguageId, second.questionLanguageId);
  assert.equal(first.stem, second.stem);
  for (const difficultyBand of ["Easy", "Medium", "Hard"]) {
    const eligible = entries2.some(
      (entry) => entry.cpId === cpId && entry.difficulty === difficultyBand
    );
    if (!eligible) continue;
    const pkg = runPnl001ReviewPipeline(cpId, {
      difficultyBand,
      seed: `${cpId}:${difficultyBand}`
    });
    assert.equal(pkg.difficultyBand, difficultyBand);
  }
}
assert.throws(
  () => runPnl001ReviewPipeline("PNL-CP-001", { language: "hi" }),
  /English only/
);
assert.throws(
  () => runPnl001ReviewPipeline("PNL-CP-001", {
    questionLanguageId: "PNL-QL-095"
  }),
  /belongs to PNL-CP-004/
);
